    [Fact]
    public void The_help_desk_ticket_matches_the_contract()
    {
        var source = Ticket().Replace(GeneratedText.Version, "<version>", StringComparison.Ordinal);

        foreach (var fragment in _contract)
        {
            source.ShouldContain(fragment.ReplaceLineEndings("\n"));
        }

        source.ShouldEndWith(_contract[^1].ReplaceLineEndings("\n"));
    }

    [Fact]
    public void Generated_text_ends_lines_with_a_line_feed_only() => Ticket().ShouldNotContain('\r');

    [Fact]
    public void Not_caller_writable_fields_have_no_setter_and_no_parameter()
    {
        var source = Ticket();

        foreach (var maintained in new[] { "Id", "EstimateCost", "CreatedAt", "CreatedBy", "UpdatedAt", "UpdatedBy" })
        {
            source.ShouldContain($" {maintained} => ");
            source.ShouldNotContain($"Set{maintained}(");
        }

        source.ShouldNotContain("estimateCost", Case.Sensitive);
        source.ShouldNotContain("createdAt", Case.Sensitive);
    }

    [Fact]
    public void A_scoped_entity_takes_tenantId_last()
    {
        var model = GeneratorHarness.Model(Descriptors.With(
            "{ \"jobs\": { \"fields\": { \"code\": { \"type\": \"string\", \"required\": true }, \"note\": { \"type\": \"text\" } } } }",
            "\"tenancy\": { \"enabled\": true },"));

        var source = EntityEmitter.Emit(model, model.Entities[0]);

        source.ShouldContain("Create(string code, string? note = null, global::System.Guid? tenantId = null) =>");
        source.ShouldContain("[\"code\"] = code, [\"note\"] = note, [\"tenant_id\"] = tenantId,");
        source.ShouldContain("public global::System.Guid TenantId => ");
        source.ShouldNotContain("SetTenantId(");
    }

    [Fact]
    public void A_required_field_with_a_default_is_an_optional_parameter()
    {
        var model = GeneratorHarness.Model(Descriptors.With(
            "{ \"jobs\": { \"fields\": { \"state\": { \"type\": \"string\", \"required\": true, \"default\": \"new\" }, \"code\": { \"type\": \"string\", \"required\": true } } } }"));

        EntityEmitter.Emit(model, model.Entities[0]).ShouldContain("Create(string code, string? state = null) =>");
    }

    [Fact]
    public void A_virtual_field_reads_null_when_the_record_does_not_carry_it()
    {
        var model = GeneratorHarness.Model(Descriptors.With(
            "{ \"jobs\": { \"fields\": { \"label\": { \"type\": \"string\", \"required\": true, \"virtual\": true } } } }"));

        var source = EntityEmitter.Emit(model, model.Entities[0]);

        source.ShouldContain("public string? Label => Record.Values.ContainsKey(\"label\") ? global::MMLib.Alvo.Data.AlvoRecordExtensions.Get<string?>(Record, \"label\") : null;");
        source.ShouldNotContain("SetLabel(");
    }

    [Fact]
    public void Roles_list_the_built_ins_then_the_declared_ones_once()
    {
        var model = GeneratorHarness.Model(Descriptors.With("{}", "\"auth\": { \"roles\": [\"agent\", \"admin\", \"field-tech\", \"agent\"] },"));

        var source = RolesEmitter.Emit(model).Replace(GeneratedText.Version, "<version>", StringComparison.Ordinal);

        source.ShouldBe("""
            // <auto-generated/>
            // Generated by MMLib.Alvo.Analyzers from project 'help-desk'. Edits are lost on rebuild.
            #nullable enable

            namespace HelpDesk;

            /// <summary>The roles of project 'help-desk': the built-in ones, then those its descriptor declares.</summary>
            [global::System.CodeDom.Compiler.GeneratedCode("MMLib.Alvo.Analyzers", "<version>")]
            public static class HelpDeskRoles
            {
                /// <summary>The role 'anon'.</summary>
                public const string Anon = "anon";

                /// <summary>The role 'authenticated'.</summary>
                public const string Authenticated = "authenticated";

                /// <summary>The role 'admin'.</summary>
                public const string Admin = "admin";

                /// <summary>The role 'agent'.</summary>
                public const string Agent = "agent";

                /// <summary>The role 'field-tech'.</summary>
                public const string FieldTech = "field-tech";
            }

            """.ReplaceLineEndings("\n"));
    }

    [Theory]
    [InlineData(FieldType.String)]
    [InlineData(FieldType.Text)]
    [InlineData(FieldType.Integer)]
    [InlineData(FieldType.Decimal)]
    [InlineData(FieldType.Boolean)]
    [InlineData(FieldType.Date)]
    [InlineData(FieldType.DateTime)]
    [InlineData(FieldType.Uuid)]
    [InlineData(FieldType.Ref)]
    public void Every_field_type_maps_to_the_applied_schema_s_CLR_type(FieldType type)
    {
        var model = GeneratorHarness.Model(Descriptors.With(
            $"{{ \"x\": {{ \"fields\": {{ \"f\": {{ \"type\": \"{type.ToString().ToLowerInvariant()}\", \"required\": true, \"precision\": 5, \"scale\": 1, \"entity\": \"x\" }} }} }} }}"));

        var emitted = EntityEmitter.ClrType(model, model.Entities[0].Fields[1]);

        Resolved(emitted).ShouldBe(FieldClrType.Of(type));
    }

    [Theory]
    [MemberData(nameof(DescriptorJsonTests.Examples), MemberType = typeof(DescriptorJsonTests))]
    public void Every_example_emits_code_that_compiles_without_a_warning(string example)
    {
        var model = GeneratorHarness.Model(File.ReadAllText(Path.Combine(RepositoryRoot.Find(), example)));

        GeneratorHarness.Problems(GeneratorHarness.Sources(model)).ShouldBeEmpty();
    }

    private static Type Resolved(string emitted) => emitted switch
    {
        "string" => typeof(string),
        "long" => typeof(long),
        "decimal" => typeof(decimal),
        "bool" => typeof(bool),
        _ => Type.GetType(emitted["global::".Length..], throwOnError: true)!,
    };

    private static string Ticket()
    {
        var model = GeneratorHarness.Model(Descriptors.HelpDesk);

        return EntityEmitter.Emit(model, model.Entities[0]);
    }
}
